use std::{fs,io::{Cursor,Write},path::{Path,PathBuf},sync::atomic::{AtomicU64,Ordering}};
static COUNTER:AtomicU64=AtomicU64::new(0);
pub struct Temp(pub PathBuf);
impl Temp {pub fn new()->Self{loop{let n=COUNTER.fetch_add(1,Ordering::Relaxed);let path=std::env::temp_dir().join(format!("docconvert-test-{}-{n}",std::process::id()));match fs::create_dir(&path){Ok(())=>return Self(path),Err(e)if e.kind()==std::io::ErrorKind::AlreadyExists=>continue,Err(e)=>panic!("test temp directory: {e}")}}}pub fn write(&self,name:&str,bytes:&[u8])->PathBuf{let path=self.0.join(name);fs::create_dir_all(path.parent().unwrap()).unwrap();fs::write(&path,bytes).unwrap();path}}
impl Drop for Temp{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
pub fn zip(parts:&[(&str,&[u8])])->Vec<u8>{let mut writer=zip::ZipWriter::new(Cursor::new(Vec::new()));for(name,data)in parts{writer.start_file(*name,zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Stored)).unwrap();writer.write_all(data).unwrap()}writer.finish().unwrap().into_inner()}
