/// BIFF8 workbook inside a minimal CFB v3 container, built entirely from source.
pub fn xls()->Vec<u8>{
 fn rec(out:&mut Vec<u8>,id:u16,payload:&[u8]){out.extend(id.to_le_bytes());out.extend((payload.len()as u16).to_le_bytes());out.extend(payload)}
 fn bof(kind:u16)->Vec<u8>{let mut p=vec![];p.extend(0x0600u16.to_le_bytes());p.extend(kind.to_le_bytes());p.extend(0x0dbbu16.to_le_bytes());p.extend(0x07ccu16.to_le_bytes());p.extend(0x41u32.to_le_bytes());p.extend(0x06u32.to_le_bytes());p}
 let mut globals=vec![];rec(&mut globals,0x0809,&bof(0x0005));rec(&mut globals,0x0042,&1252u16.to_le_bytes());
 // BOUNDSHEET: stream position follows globals; fixed payload is 8+4-byte name.
 let sheet_offset=(globals.len()+4+12+4)as u32;let mut bound=vec![];bound.extend(sheet_offset.to_le_bytes());bound.extend([0,0,4,0]);bound.extend(b"Data");rec(&mut globals,0x0085,&bound);rec(&mut globals,0x000a,&[]);
 let mut worksheet=vec![];rec(&mut worksheet,0x0809,&bof(0x0010));let mut dim=vec![];dim.extend(0u32.to_le_bytes());dim.extend(1u32.to_le_bytes());dim.extend(0u16.to_le_bytes());dim.extend(1u16.to_le_bytes());dim.extend(0u16.to_le_bytes());rec(&mut worksheet,0x0200,&dim);
 let mut formula=vec![0;6];formula.extend(3f64.to_le_bytes());formula.extend([0;6]);let tokens=[0x1e,1,0,0x1e,2,0,0x03];formula.extend((tokens.len()as u16).to_le_bytes());formula.extend(tokens);rec(&mut worksheet,0x0006,&formula);rec(&mut worksheet,0x000a,&[]);globals.extend(worksheet);globals.resize(4096,0);
 const FREE:u32=0xffff_ffff;const END:u32=0xffff_fffe;const FAT:u32=0xffff_fffd;
 let mut header=vec![0u8;512];header[..8].copy_from_slice(b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1");header[24..26].copy_from_slice(&0x003eu16.to_le_bytes());header[26..28].copy_from_slice(&3u16.to_le_bytes());header[28..30].copy_from_slice(&0xfffeu16.to_le_bytes());header[30..32].copy_from_slice(&9u16.to_le_bytes());header[32..34].copy_from_slice(&6u16.to_le_bytes());header[44..48].copy_from_slice(&1u32.to_le_bytes());header[48..52].copy_from_slice(&8u32.to_le_bytes());header[56..60].copy_from_slice(&4096u32.to_le_bytes());header[60..64].copy_from_slice(&END.to_le_bytes());header[68..72].copy_from_slice(&END.to_le_bytes());for i in 0..109{header[76+i*4..80+i*4].copy_from_slice(&FREE.to_le_bytes())}header[76..80].copy_from_slice(&9u32.to_le_bytes());
 fn entry(name:&str,kind:u8,start:u32,size:u64,child:u32)->Vec<u8>{let mut e=vec![0u8;128];let name=name.encode_utf16().chain(std::iter::once(0)).collect::<Vec<_>>();for(i,c)in name.iter().enumerate(){e[i*2..i*2+2].copy_from_slice(&c.to_le_bytes())}e[64..66].copy_from_slice(&((name.len()*2)as u16).to_le_bytes());e[66]=kind;e[67]=1;e[68..72].copy_from_slice(&0xffff_ffffu32.to_le_bytes());e[72..76].copy_from_slice(&0xffff_ffffu32.to_le_bytes());e[76..80].copy_from_slice(&child.to_le_bytes());e[116..120].copy_from_slice(&start.to_le_bytes());e[120..128].copy_from_slice(&size.to_le_bytes());e}
 let mut directory=entry("Root Entry",5,END,0,1);directory.extend(entry("Workbook",2,0,4096,FREE));directory.resize(512,0);let mut fat=vec![];for i in 0..128u32{fat.extend(match i{0..=6=>i+1,7|8=>END,9=>FAT,_=>FREE}.to_le_bytes())}header.extend(globals);header.extend(directory);header.extend(fat);header
}

pub fn zip_patch(bytes:&[u8],changes:&[(&str,&[u8])])->Vec<u8>{
    use std::io::Read;
    let mut archive=zip::ZipArchive::new(Cursor::new(bytes)).unwrap();
    let mut parts=std::collections::BTreeMap::new();
    for i in 0..archive.len(){let mut member=archive.by_index(i).unwrap();if member.is_dir(){continue}let name=member.name().to_owned();let mut data=vec![];member.read_to_end(&mut data).unwrap();parts.insert(name,data);}
    for(name,data)in changes{parts.insert((*name).into(),data.to_vec());}
    let refs:Vec<_>=parts.iter().map(|(name,data)|(name.as_str(),data.as_slice())).collect();zip(&refs)
}

/// Minimal uncompressed PDF, generated from text streams with a real xref table.
pub fn pdf_streams(streams:&[&str])->Vec<u8>{let mut objects=vec![b"<< /Type /Catalog /Pages 2 0 R >>".to_vec(),vec![],b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>".to_vec()];let mut kids=vec![];for s in streams{let page=objects.len()+1;let content=page+1;kids.push(format!("{page} 0 R"));objects.push(format!("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 800] /Resources << /Font << /F1 3 0 R >> >> /Contents {content} 0 R >>").into_bytes());objects.push(format!("<< /Length {} >>\nstream\n{}\nendstream",s.len(),s).into_bytes())}objects[1]=format!("<< /Type /Pages /Count {} /Kids [{}] >>",streams.len(),kids.join(" ")).into_bytes();let mut out=b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n".to_vec();let mut offsets=vec![0];for(i,object)in objects.iter().enumerate(){offsets.push(out.len());out.extend(format!("{} 0 obj\n",i+1).as_bytes());out.extend(object);out.extend(b"\nendobj\n")}let xref=out.len();out.extend(format!("xref\n0 {}\n0000000000 65535 f \n",offsets.len()).as_bytes());for off in &offsets[1..]{out.extend(format!("{off:010} 00000 n \n").as_bytes())}out.extend(format!("trailer\n<< /Size {} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n",offsets.len()).as_bytes());out}
pub fn fake_ocr(dir:&Path)->PathBuf{let binary=dir.join(if cfg!(windows){"fake-ocr.exe"}else{"fake-ocr"});let status=std::process::Command::new("rustc").arg("--edition=2021").arg(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/fake-ocr/main.rs")).arg("-o").arg(&binary).status().expect("rustc needed for source-only OCR fixture");assert!(status.success());binary}
